# Generated by build.py from recipe.yml for recipe oci-list-tags-with-a-registry-token. Do not edit.
Set-Location $PSScriptRoot
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '--directory', 'store', '--cert', 'server.pem', '--key', 'server.key', '--user', 'alice:s3cret', 'oci://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh tags.sh https://127.0.0.1:8080/ alice:s3cret demo/app } finally { Stop-Process $server0 }
